'use client';

import { useState, useEffect } from 'react';
import { getResult } from '../../services/api';
import { motion } from 'framer-motion';
import Link from 'next/link';

export default function ResultsPage() {
    const [result, setResult] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const userId = localStorage.getItem('disc_user_id');
        if (!userId) {
            // Redirect to login if not authenticated
            window.location.href = '/login';
            return;
        }

        const fetchResult = async () => {
            try {
                const data = await getResult(userId);
                setResult(data);
            } catch (error) {
                console.error("Failed to fetch result", error);
            } finally {
                setLoading(false);
            }
        };
        fetchResult();
    }, []);

    // Prevent back navigation to assessment page
    useEffect(() => {
        // Replace current history state so back button goes to dashboard
        window.history.replaceState(null, '', '/results');

        const handlePopState = () => {
            // Redirect to dashboard when back button is pressed
            window.location.href = '/';
        };

        window.addEventListener('popstate', handlePopState);

        return () => {
            window.removeEventListener('popstate', handlePopState);
        };
    }, []);

    if (loading) return <div className="min-h-screen flex items-center justify-center bg-black text-cyan-400">Analysis in progress...</div>;

    if (!result) return <div className="min-h-screen flex items-center justify-center bg-black text-red-500">No results found.</div>;

    // Descriptions for DISCs
    const traits = {
        D: { name: 'Dominance', color: 'text-red-500', desc: "Assertive, ambitious, and results-oriented." },
        I: { name: 'Influence', color: 'text-yellow-400', desc: "Enthusiastic, persuasive, and optimistic." },
        S: { name: 'Steadiness', color: 'text-green-400', desc: "Supportive, patient, and loyal." },
        C: { name: 'Conscientiousness', color: 'text-blue-400', desc: "Analytical, precise, and systematic." }
    };

    const highest = traits[result.highestTrait] || {};

    return (
        <main className="min-h-screen flex flex-col items-center justify-center p-8 bg-black relative">
            <div className="absolute top-0 left-0 w-full h-full overflow-hidden z-0">
                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-gradient-to-r from-cyan-500/20 to-purple-500/20 rounded-full blur-[120px]" />
            </div>

            <motion.div
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.8 }}
                className="z-10 text-center space-y-8 max-w-4xl"
            >
                <h1 className="text-4xl font-thin text-zinc-300">Your Primary Trait is</h1>

                <div className="glass-panel p-12 rounded-3xl border border-white/10">
                    <h2 className={`text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-bold ${highest.color} mb-4 neon-text break-words leading-tight`}>
                        {highest.name || result.highestTrait}
                    </h2>
                    <p className="text-xl md:text-2xl text-zinc-300 mt-4 font-light">
                        {highest.desc}
                    </p>
                </div>

                <div className="grid grid-cols-4 gap-4 mt-8">
                    {Object.entries(result.score).map(([key, val]) => (
                        <div key={key} className="flex flex-col items-center p-4 glass-panel rounded-xl">
                            <span className={`text-2xl font-bold ${traits[key].color}`}>{key}</span>
                            <span className="text-white text-lg">{val}</span>
                        </div>
                    ))}
                </div>

                <div className="flex gap-4 mt-12">
                    <Link href="/" className="inline-block px-8 py-3 rounded-full bg-gradient-to-r from-cyan-600 to-blue-600 text-white font-bold hover:scale-105 transition-transform shadow-[0_0_30px_rgba(34,211,238,0.4)]">
                        Go to Dashboard
                    </Link>
                    <Link href="/" className="inline-block px-8 py-3 rounded-full bg-white/10 hover:bg-white/20 transition-colors text-white border border-white/20">
                        Retake Assessment
                    </Link>
                </div>
            </motion.div>
        </main>
    );
}
